{"path": "/tmp/sv-afc552f350534bb79e67654e834fa222/Components/Pages/Chat/MessageArea.razor", "file_text": "@using sv_afc552f350534bb79e67654e834fa222.Services
@inject IJSRuntime JS

<div class="message-area">
    @if (Channel is not null)
    {
        <div class="area-header">
            <h2># @Channel.Name</h2>
            @if (!string.IsNullOrWhiteSpace(Channel.Description))
            {
                <span class="area-desc">@Channel.Description</span>
            }
        </div>

        <div class="message-list" @ref="_scrollContainer" @onscroll="HandleScroll">
            @if (IsLoadingMore)
            {
                <div class="loading-indicator">Loading older messages…</div>
            }
            @if (HasMoreMessages && !IsLoadingMore)
            {
                <div class="load-more-hint">Scroll up for older messages</div>
            }
            @foreach (var msg in Messages)
            {
                <MessageItem Message="msg"
                             ReplyCount="GetReplyCount(msg.Id)"
                             OnOpenThread="() => OnOpenThread.InvokeAsync(msg.Id)"
                             OnReact="(emoji) => OnReact.InvokeAsync((msg.Id, emoji))" />
            }
        </div>

        <MessageInput Placeholder="@($"Message #{Channel.Name}")" OnSend="OnSendMessage" />
    }
    else
    {
        <div class="empty-state">
            <p>Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter] public Channel? Channel { get; set; }
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, ThreadSummary> ThreadSummaries { get; set; } = new();
    [Parameter] public bool HasMoreMessages { get; set; }
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private ElementReference _scrollContainer;

    private int GetReplyCount(int messageId) =>
        ThreadSummaries.TryGetValue(messageId, out var summary) ? summary.ReplyCount : 0;

    private async Task HandleScroll()
    {
        if (IsLoadingMore || !HasMoreMessages) return;

        var scrollTop = await JS.InvokeAsync<double>("eval", $"document.querySelector('[_bl_{_scrollContainer.Id}]')?.scrollTop ?? 1");
        if (scrollTop < 50)
        {
            await OnLoadMore.InvokeAsync();
        }
    }
}
"}

