<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="() => OnClose.InvokeAsync()">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root">
            <MessageItem Message="RootMessage" ShowReplyButton="false" IsHighlighted="true"
                         OnReact="(emoji) => OnReact.InvokeAsync((RootMessage.Id, emoji))" />
        </div>

        <div class="thread-divider">
            <span>@Replies.Count @(Replies.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <MessageItem Message="reply" ShowReplyButton="false"
                             OnReact="(emoji) => OnReact.InvokeAsync((reply.Id, emoji))" />
            }
        </div>

        <MessageInput Placeholder="Reply to thread…" ButtonLabel="Reply" OnSend="OnSendReply" />
    }
</div>

@code {
