arguments.file_text:
@page "/chat"
@using sv_afc552f350534bb79e67654e834fa222.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="sidebar-panel">
        <ChannelSidebar Channels="_channels"
                        ActiveChannelId="_activeChannelId"
                        OnChannelSelected="SelectChannelAsync" />
    </div>

    <div class="main-panel @(_threadRootMessage is null ? "full-width" : "")">
        <MessageArea Channel="_activeChannel"
                     Messages="_messages"
                     ThreadSummaries="_threadSummaries"
                     HasMoreMessages="_hasMoreMessages"
                     IsLoadingMore="_isLoadingMore"
                     OnSendMessage="SendMessageAsync"
                     OnOpenThread="OpenThreadAsync"
                     OnReact="HandleReactionAsync"
                     OnLoadMore="LoadMoreMessagesAsync" />
    </div>

    @if (_threadRootMessage is not null)
    {
        <div class="thread-panel-container">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReplyAsync"
                         OnReact="HandleReactionAsync" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> _channels = [];
    private int? _activeChannelId;
    private Channel? _activeChannel;
    private List<Message> _messages = [];
    private Dictionary<int, ThreadSummary> _threadSummaries = new();
    private bool _hasMoreMessages;
    private bool _isLoadingMore;

    // Thread state
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannelAsync(_channels[0].Id);
        }
    }

    private async Task SelectChannelAsync(int channelId)
    {
        if (_activeChannelId == channelId) return;

        _activeChannelId = channelId;
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messages = [];
        _threadSummaries = new();
        _threadRootMessage = null;
        _threadReplies = [];

        var messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messages = messages;
        _hasMoreMessages = messages.Count == PageSize;

        await BuildThreadSummariesAsync();
        await ChatService.MarkChannelReadAsync(channelId);

        // Refresh channel list to update unread counts
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadMoreMessagesAsync()
    {
        if (_isLoadingMore || !_hasMoreMessages || _activeChannelId is null) return;

        _isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId.Value, _messages.Count, PageSize);
        _hasMoreMessages = older.Count == PageSize;

        // Prepend older messages
        _messages.InsertRange(0, older);
        await BuildThreadSummariesAsync();

        _isLoadingMore = false;
    }

    private async Task SendMessageAsync(string content)
    {
        if (_activeChannelId is null) return;

        var msg = await ChatService.SendMessageAsync(_activeChannelId.Value, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThreadAsync(int messageId)
    {
        var rootMsg = _messages.FirstOrDefault(m => m.Id == messageId);
        if (rootMsg is null) return;

        _threadRootMessage = rootMsg;
        _threadReplies = await ChatService.GetThreadAsync(messageId);
    }

    private void CloseThread()
    {
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReplyAsync(string content)
    {
        if (_threadRootMessage is null || _activeChannelId is null) return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update thread summary count
        if (_threadSummaries.TryGetValue(_threadRootMessage.Id, out var summary))
        {
            _threadSummaries[_threadRootMessage.Id] = summary with
            {
                ReplyCount = summary.ReplyCount + 1,
                LastReplyAt = reply.SentAt
            };
        }
        else
        {
            _threadSummaries[_threadRootMessage.Id] = new ThreadSummary(
                _threadRootMessage.Id, 1, reply.SentAt);
        }
    }

    private async Task HandleReactionAsync((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Refresh the message in the main list
        if (_activeChannelId is not null)
        {
            var refreshed = await ChatService.GetMessagesAsync(_activeChannelId.Value, 0, _messages.Count);
            _messages = refreshed;
        }

        // Refresh thread if open
        if (_threadRootMessage is not null)
        {
            _threadReplies = await ChatService.GetThreadAsync(_threadRootMessage.Id);
            _threadRootMessage = _messages.FirstOrDefault(m => m.Id == _threadRootMessage.Id) ?? _threadRootMessage;
        }
    }

    private async Task BuildThreadSummariesAsync()
    {
        // Build thread summaries for messages that have replies
        // Look for messages that are replied to by other messages in the list
        var rootIds = _messages
            .Where(m => m.ReplyToId is not null)
            .Select(m => m.ReplyToId!.Value)
            .Distinct();

        foreach (var rootId in rootIds)
        {
            if (!_threadSummaries.ContainsKey(rootId))
            {
                var thread = await ChatService.GetThreadAsync(rootId);
                if (thread.Count > 0)
                {
                    _threadSummaries[rootId] = new ThreadSummary(
                        rootId,
                        thread.Count,
                        thread.Max(t => t.SentAt));
                }
            }
        }
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.sidebar-panel {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.main-panel {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    transition: flex 0.2s ease;
}

.main-panel.full-width {
    flex: 1;
}

.thread-panel-container {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    flex-shrink: 0;
}

